package org.concordia.babycdf;
import org.junit.jupiter.api.Test;import com.daml.ledger.api.v2.*;import java.util.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static org.concordia.babycdf.SourceCatalogueCodec.*;
class IntegratedDeliveryReviewTest {
 @Test void validDeliveryReviewedAndSnapshotFieldMutationsRejected()throws Exception {
  Instant now=Instant.parse("2026-11-23T00:00:00Z");String commit="a".repeat(40),content="CAP evidence",blob=EvidenceBundle.blob(content);var o=new SourceObservation(540,SourceObservation.Kind.MILESTONE,"https://github.com/"+ConcordiaDemoScope.REPO+"/issues/540","Concordia",SourceObservation.hash("body"),"open",now,now,184L,"parent",false,SourceObservation.hash("body"),false);var obs=observation(o);String fingerprint=SourceCatalogueDigest.digest(obs.getRecord());var none=ValueOuterClass.Value.newBuilder().setOptional(ValueOuterClass.Optional.getDefaultInstance()).build();var party=ValueOuterClass.Value.newBuilder().setParty("opener").build();
  var pin=ValueOuterClass.Value.newBuilder().setVariant(ValueOuterClass.Variant.newBuilder().setConstructor("DeliveryPin").setValue(record("deliveryCommit",text(commit),"issueDigest",text(o.bodySha256()),"voteCommentId",integer(123),"voteCommentAt",timestamp(now)))).build();
  var snapshot=record("sourceCid",ValueOuterClass.Value.newBuilder().setContractId("credential").build(),"opener",party,"observation",obs,"fingerprint",text(fingerprint),"version",integer(1),"previousDigest",none,"evidenceDigest",text(o.bodySha256()),"pin",pin,"roundId",text("540"),"originalProposal",integer(184),"previousRound",none);
  java.util.function.Function<ValueOuterClass.Value,EventOuterClass.CreatedEvent> event=s->EventOuterClass.CreatedEvent.newBuilder().setContractId("agenda").addSignatories("opener").addWitnessParties("opener").setCreateArguments(record("opener",party,"roundId",text("540"),"subject",record("url",text(o.url()),"body",text(fingerprint)),"sourceSnapshot",ValueOuterClass.Value.newBuilder().setOptional(ValueOuterClass.Optional.newBuilder().setValue(s)).build()).getRecord()).build();
  var valid=event.apply(snapshot);assertNotNull(IntegratedAgendaSnapshot.decode(valid).delivery());
  for(String missing:List.of("sourceCid","version","previousDigest","originalProposal")){var changed=snapshot.getRecord().toBuilder().clearFields();for(var f:snapshot.getRecord().getFieldsList())if(!f.getLabel().equals(missing))changed.addFields(f);assertThrows(java.io.IOException.class,()->IntegratedAgendaSnapshot.decode(event.apply(ValueOuterClass.Value.newBuilder().setRecord(changed).build())),missing);}
  var gateway=new Reviewer.LedgerRuleGateway(){public List<Reviewer.EffectiveRule> activeRules(){return List.of(new Reviewer.EffectiveRule("active","architecture-review",1,List.of(new Advisory.Clause("c1","a","CAP evidence","b","wrong"))));}public List<EventOuterClass.CreatedEvent> agendaEvents(){return List.of(valid);}};
  var providerCalls=new java.util.concurrent.atomic.AtomicInteger();var settings=LlmSettings.fromEnvironment(Map.of("LLM_API_KEY","synthetic"));byte[] response=SupplementalAssessmentTest.response(SupplementalAssessmentTest.valid("PASS",""));var supplemental=new SupplementalAssessment("Reviewer",settings,new LlmClient(settings,r->{providerCalls.incrementAndGet();return SupplementalAssessmentTest.reply(200,response);},System::nanoTime,false),null,System.out);
  Advisory.Api evidence=path->Advisory.JSON.readTree(path.contains("commits")?"{\"sha\":\""+commit+"\",\"commit\":{\"committer\":{\"date\":\"2026-11-22T00:00:00Z\"}}}":path.contains("trees")?"{\"truncated\":false,\"tree\":[{\"path\":\"docs/delivery.md\",\"type\":\"blob\",\"sha\":\""+blob+"\"}]}":"{\"encoding\":\"base64\",\"content\":\""+Base64.getEncoder().encodeToString(content.getBytes())+"\"}");
  var result=new AgendaFollowingReview(evidence,supplemental).cycle(gateway);assertTrue(result.path("reviews").get(0).path("pinned").asBoolean());assertFalse(result.path("reviews").get(0).path("absence_eligible").asBoolean());assertFalse(result.path("reviews").get(0).path("head_consistent").asBoolean());assertEquals("pass",result.path("reviews").get(0).path("findings").get(0).path("status").asText());assertEquals(1,providerCalls.get());
  assertThrows(java.io.IOException.class,()->new AgendaFollowingReview(path->Advisory.JSON.readTree("{\"sha\":\"wrong\"}")).cycle(gateway));
 }
}
